package echo

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestZZFuzz(t *testing.T) {
	routes := [][2]string{
		{http.MethodGet, "/"},
		{http.MethodGet, "/users/:id"},
		{http.MethodGet, "/users/new"},
		{http.MethodGet, "/static/*"},
		{http.MethodGet, "/a/:b/c/:d"},
		{http.MethodPost, "/api/*"},
	}
	paths := []string{"", "/", "//", "abc", "/abc", "/users", "/users/", "/users/1", "/users/1/", "/users/new", "/static/", "/static/x/y", "/a/1/c/2", "/a/1/c", "/a//c/2", "/api", "/api/", "/api/x", "*", "/users/1/2/3", "/a/1/c/2/3", "/:x", "/users/:id", "/static", "/a", "/a/1", "/a/1/", "/users/new/", "/zzz", "/u", "/us", "/user", "/users/n", "/a/1/c/2/"}
	for _, r := range routes {
		e := New()
		e.Add(r[0], r[1], func(c Context) error { return nil })
		for _, p := range paths {
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						t.Errorf("PANIC route=%s %s path=%q: %v", r[0], r[1], p, rec)
					}
				}()
				req := httptest.NewRequest(r[0], "/", nil)
				rec := httptest.NewRecorder()
				c := e.NewContext(req, rec)
				e.Router().Find(r[0], p, c)
			}()
		}
	}
	// multiple routes together
	e := New()
	for _, r := range routes {
		e.Add(r[0], r[1], func(c Context) error { return nil })
	}
	for _, p := range paths {
		for _, m := range []string{http.MethodGet, http.MethodPost, "NOPE"} {
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						t.Errorf("PANIC multi method=%s path=%q: %v", m, p, rec)
					}
				}()
				req := httptest.NewRequest(http.MethodGet, "/", nil)
				rec := httptest.NewRecorder()
				c := e.NewContext(req, rec)
				e.Router().Find(m, p, c)
			}()
		}
	}
}
EOF
