package echo

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func find(e *Echo, method, p string) (string, bool) {
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	rec := httptest.NewRecorder()
	c := e.NewContext(req, rec)
	e.Router().Find(method, p, c)
	// determine matched route path via handler pointer
	h := c.Handler()
	for _, r := range e.Routes() {
		if r.Method == method {
			// can't compare funcs; use path from context
			_ = r
		}
	}
	return c.Path(), h != nil
}

func TestZZAnySplit(t *testing.T) {
	e := New()
	e.Add(http.MethodGet, "/a/*", func(c Context) error { return nil })
	e.Add(http.MethodGet, "/ab", func(c Context) error { return nil })
	for _, p := range []string{"/a/x", "/a/x/y", "/ab", "/a/"} {
		path, _ := find(e, http.MethodGet, p)
		t.Logf("path=%q -> matched route %q", p, path)
	}
}

func TestZZAnySplit2(t *testing.T) {
