	e.Add(http.MethodGet, "/a/*", func(c Context) error { return nil })
	e.Add(http.MethodGet, "/abc", func(c Context) error { return nil })
	for _, p := range []string{"/a/x", "/abc"} {
		path, _ := find(e, http.MethodGet, p)
		t.Logf("path=%q -> matched route %q", p, path)
	}
}
