func TestZZVerify(t *testing.T) {
	// map[string][]string
	b := new(DefaultBinder)
	m := map[string][]string{}
	if err := b.bindData(&m, map[string][]string{"a": {"1", "2"}}, "query"); err != nil {
		t.Fatal(err)
	}
	t.Logf("map=%v", m)
	// map[string]string still works
	m2 := map[string]string{}
	if err := b.bindData(&m2, map[string][]string{"a": {"1"}}, "query"); err != nil {
		t.Fatal(err)
	}
	t.Logf("map2=%v", m2)
	// Scheme
	c := &context{request: &http.Request{Header: http.Header{HeaderXForwardedProto: []string{"bogus"}, HeaderXForwardedProtocol: []string{"https"}}}}
	t.Logf("scheme=%q", c.Scheme())
	c2 := &context{request: &http.Request{Header: http.Header{HeaderXForwardedProto: []string{"bogus"}}}}
	t.Logf("scheme2=%q", c2.Scheme())
}
EOF
